		value = value<<7 | uint32(b&0x7f)
		count++
		if b&0x80 != 0 {
			continue
		}
		out = append(out, value)
		value = 0
		count = 0
	}

	if count != 0 {
		return nil, ErrIncomplete
	}
	return out, nil
